#!/bin/sh
# 增量构建：第二次 make 什么都不做，改一个 .c 只重编一个 .o
# 期望输出见 expected_output（本机 MinGW 工具链 + GNU Make 真实执行捕获）

cat > Makefile << 'EOF'
CC := D:/mingw64/bin/gcc.exe
CFLAGS := -std=c11 -O2 -Wall
TARGET := app.exe
OBJS := main.o util.o

$(TARGET): $(OBJS)
	$(CC) $(CFLAGS) -o $@ $^

%.o: %.c
	$(CC) $(CFLAGS) -c $< -o $@

.PHONY: clean status
clean:
	@rm -f $(TARGET) $(OBJS)

status:
	@echo "artifacts: [$(wildcard *.o)] [$(wildcard *.d)]"
EOF

cat > main.c << 'EOF'
#include <stdio.h>
#include "util.h"

int main(void)
{
    printf("add(2, 3) = %d\n", add(2, 3));
    return 0;
}
EOF

cat > util.c << 'EOF'
#include "util.h"

int add(int a, int b)
{
    return a + b;
}
EOF

cat > util.h << 'EOF'
int add(int a, int b);
EOF

mingw32-make
mingw32-make            # 第二次：应 up to date
touch -d '2 minutes ago' main.o util.o app.exe   # 把产物时间回拨，便于观察
touch -d '2 minutes ago' util.o
touch -d '2 minutes ago' app.exe
touch util.c            # 只改 util.c
mingw32-make            # 只应重编 util.o 并重新链接
mingw32-make            # 再次：又回到 up to date
